using System;
class CheckBuffChecks {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Main(){var effect=new CheckSpellEffect();effect.Guidance(true,3,100);Check(effect.Guided(true,3,109)&&effect.Guided(true,3,109),"guidance is repeatable");Check(!effect.Guided(true,2,109)&&!effect.Guided(true,-1,109)&&!effect.Guided(false,3,109),"chosen skill and target only");Check(!effect.Guided(true,3,110),"one minute expiry");effect.Clear();effect.Enhance(true,0,200);effect.Enhance(false,4,200);Check(effect.Advantage(true,0,799)&&effect.Advantage(false,4,799)&&!effect.Advantage(true,4,799),"independent abilities for upcast targets");Check(!effect.Advantage(true,0,800),"one hour expiry");bool invalid=false;try{effect.Enhance(true,2,0);}catch(ArgumentOutOfRangeException){invalid=true;}Check(invalid,"constitution unavailable");effect.Clear();Check(!effect.Advantage(false,4,200)&&!effect.Guided(true,3,100),"concentration clear");Check(DirectSpell.Find("Guidance").Range==5&&DirectSpell.Find("Enhance Ability").Level==2,"spell definitions");Console.WriteLine("PASS: guidance targeting, repeated uses, expiry; enhance ability choices, multiple targets and concentration clear");}
}
